package org.pocketsurf.browser

import android.content.Intent
import android.graphics.Rect
import android.net.Uri
import android.os.Looper
import android.view.*
import android.webkit.WebView
import android.widget.*
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.Config
import java.time.Duration

/** Native controller/layout fixtures; these assertions do not simulate Chromium rendering. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk=[33],qualifiers="w960dp-h540dp-land-mdpi",shadows=[RecordingWebViewShadow::class])
class Chrome05RegressionTest {
 @Before fun fixtures(){RuntimeEnvironment.getApplication().getSharedPreferences("browser",0).edit().putBoolean("setup_complete",true).commit();RecordingWebViewShadow.clearEvidence()}
 private fun all(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{all(v.getChildAt(it))}else emptyList()
 private fun views(a:BrowserActivity)=all(a.window.decorView)
 private fun desc(a:BrowserActivity,s:String)=views(a).filter{it.contentDescription?.toString()==s}.let{it.firstOrNull{v->v.isShown}?:it.first()}
 private fun label(a:BrowserActivity,s:String)=views(a).filterIsInstance<TextView>().firstOrNull{it.text.toString()==s}
 private fun settle(a:BrowserActivity){repeat(3){views(a).forEach{it.forceLayout()};a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));layout(0,0,960,540)};TestFrameClock.advance(Duration.ofMillis(16))}}
 private fun start()=Robolectric.buildActivity(BrowserActivity::class.java,Intent(Intent.ACTION_VIEW,Uri.parse("https://fixture.test/"))).setup().visible().also{settle(it.get())}
 private fun key(a:BrowserActivity,k:Int){a.dispatchKeyEvent(KeyEvent(0,k));a.dispatchKeyEvent(KeyEvent(1,k));settle(a)}
 private fun click(a:BrowserActivity,s:String){if(s=="History"){if(views(a).any{it.contentDescription=="Browser menu popup"})key(a,97);desc(a,"History").performClick();settle(a);return};var v:View=label(a,s)?:desc(a,s);while(!v.hasOnClickListeners())v=v.parent as View;v.performClick();settle(a)}
 private fun web(a:BrowserActivity)=views(a).filterIsInstance<WebView>().single()
 private fun address(a:BrowserActivity)=views(a).filterIsInstance<EditText>().first{it.contentDescription?.startsWith("Address or")==true}
 private fun focusAddress(a:BrowserActivity){key(a,19);if(a.window.decorView.findFocus()!==address(a))key(a,19);assertSame(address(a),a.window.decorView.findFocus())}

 @Test fun toolbarAndTopActionsUseUniformCompactSquareButtons(){val c=start();val a=c.get();val toolbar=address(a).parent.parent as ViewGroup;assertEquals(40,toolbar.height);val buttons=(0 until toolbar.childCount).map{toolbar.getChildAt(it)}.filter{it is FrameLayout&&it.visibility==View.VISIBLE&&it.contentDescription!=null};for(button in buttons+listOf(desc(a,"Downloads"),desc(a,"Share page"),desc(a,"Settings"))){assertEquals(36,button.height);val icon=(button as ViewGroup).getChildAt(0);assertEquals(18,icon.width);assertEquals(18,icon.height)};c.pause().stop().destroy()}
 @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
 @Test fun browserMenuIsARightDrawerWithOnlyRelevantActions(){val c=start();val a=c.get();val original=web(a);key(a,4);TestFrameClock.advance(Duration.ofMillis(360));settle(a);val panel=desc(a,"Browser menu panel");val page=original.parent as View;val panelBounds=Rect();val pageBounds=Rect();assertTrue(panel.getGlobalVisibleRect(panelBounds));assertTrue(page.getGlobalVisibleRect(pageBounds));assertEquals(pageBounds.right,panelBounds.right);assertTrue(panel.width<=320);assertEquals(1f,panel.alpha,.001f);assertEquals(0f,panel.translationX,.001f);for(title in listOf("Library","Page","Privacy"))assertNotNull(label(a,title));for(title in listOf("New tab","Reading zoom","Share page","Mouse mode","History"))assertTrue("Drawer contains removed $title",all(panel).none{it.contentDescription==title});for(scroll in all(panel).filterIsInstance<ScrollView>()){val section=scroll.getChildAt(0);assertFalse("Handheld drawer scrolls: panel=${panel.width}x${panel.height}, viewport=${scroll.width}x${scroll.height}, sections=${section.width}x${section.height}, range=${section.height-scroll.height}",scroll.canScrollVertically(1))};assertEquals("Bookmarks",a.window.decorView.findFocus()?.contentDescription);key(a,20);assertEquals("Downloads",a.window.decorView.findFocus()?.contentDescription);key(a,96);assertNotNull(label(a,"No downloads yet"));c.pause().stop().destroy()}
 @Test fun settingsGroupsAndLegendsDoNotOfferGlobalBrowserActions(){val c=start();val a=c.get();click(a,"Settings");for(title in listOf("Browsing","Privacy","Controls","Data","About"))assertNotNull(label(a,title));click(a,"Appearance");val before=a.window.decorView.findFocus();val preview=desc(a,"OLED theme");key(a,109);assertSame(before,a.window.decorView.findFocus());assertSame(preview,desc(a,"OLED theme"));assertTrue(views(a).none{it.contentDescription=="Browser menu popup"});assertTrue(views(a).none{it.contentDescription=="Go"&&it.isShown});val legend=views(a).filterIsInstance<HorizontalScrollView>().first{it.contentDescription?.contains(" controls:")==true};val hints=legend.getChildAt(0) as ViewGroup;assertEquals(2,hints.childCount);val copy=legend.contentDescription.toString();assertFalse(copy.contains("Browser menu"));assertFalse(copy.contains("Search"));c.pause().stop().destroy()}
 @Test fun searchShortcutFocusesHistoryQueryWithoutOpeningAddressOrMenu(){val c=start();val a=c.get();val data=BrowserData(a.getSharedPreferences("browser",0));data.record("https://first.test/","First page");data.record("https://second.test/","Second page");key(a,4);click(a,"History");key(a,109);val query=views(a).filterIsInstance<EditText>().first{it.hint=="Search history"};assertSame(query,a.window.decorView.findFocus());query.setText("Second");settle(a);assertNotNull(label(a,"Second page"));assertNull(label(a,"First page"));assertTrue(views(a).none{it.contentDescription=="Go"&&it.isShown});key(a,109);assertNotNull(label(a,"History"));assertTrue(views(a).none{it.contentDescription=="Browser menu popup"});c.pause().stop().destroy()}
 @Test fun favoritesCanBeEnabledAndNavigatedBetweenAddressAndPage(){val prefs=RuntimeEnvironment.getApplication().getSharedPreferences("browser",0);BrowserData(prefs).record("https://favorite.test/","Favorite fixture","bookmarks");val c=start();val a=c.get();assertFalse(desc(a,"Bookmarks bar").isShown);click(a,"Settings");click(a,"Bookmarks bar");desc(a,"Show bookmarks bar while browsing").performClick();settle(a);assertTrue(prefs.getBoolean("favorites_bar",false));key(a,97);key(a,97);val bar=desc(a,"Bookmarks bar");assertTrue(bar.isShown);assertEquals(30,bar.height);val favorite=desc(a,"Bookmark: Favorite fixture");assertTrue(all(favorite).any{it is SiteIconView});focusAddress(a);key(a,20);assertSame(favorite,a.window.decorView.findFocus());key(a,19);assertSame(address(a),a.window.decorView.findFocus());key(a,20);key(a,96);assertEquals("https://favorite.test/",web(a).url);click(a,"Settings");click(a,"Bookmarks bar");desc(a,"Show bookmarks bar while browsing").performClick();settle(a);key(a,97);key(a,97);assertFalse(desc(a,"Bookmarks bar").isShown);c.pause().stop().destroy()}
 @Test fun singleTabClosesWithRInOverviewAndCloseGlyphIsTouchOnly(){val c=start();val a=c.get();assertFalse(desc(a,"Close fixture.test").isFocusable);key(a,99);views(a).first{it.contentDescription=="Current tab: fixture.test"&&it.isShown}.requestFocus();key(a,103);assertNotNull(label(a,"0 tabs · choose a page to continue"));assertNull(label(a,"Close this tab?"));c.pause().stop().destroy()}
 @Test fun openingMenuAfterTheLastShortcutAlwaysStartsAtBookmarks(){val prefs=RuntimeEnvironment.getApplication().getSharedPreferences("browser",0);val shortcuts=StartPageStore(prefs);repeat(6){shortcuts.put("Fixture ${it+1}","https://fixture${it+1}.test/")};val c=Robolectric.buildActivity(BrowserActivity::class.java).setup().visible();val a=c.get();settle(a);key(a,20);key(a,22);key(a,22);assertEquals("Pinned bookmark: Fixture 6",a.window.decorView.findFocus()?.contentDescription);key(a,96);assertEquals("https://fixture6.test/",web(a).url);key(a,4);assertEquals("Bookmarks",a.window.decorView.findFocus()?.contentDescription);key(a,96);assertNotNull(label(a,"Bookmarks"));c.pause().stop().destroy()}
 @Test fun firstHomeLegendBadgeHasItsCompleteVisibleBounds(){val c=Robolectric.buildActivity(BrowserActivity::class.java).setup().visible();val a=c.get();settle(a);val host=views(a).filterIsInstance<HorizontalScrollView>().first{it.contentDescription?.contains(" controls:")==true};val row=host.getChildAt(0) as ViewGroup;val hint=row.getChildAt(0) as ViewGroup;val badge=hint.getChildAt(0) as TextView;assertEquals("A",badge.text.toString());assertEquals(14,badge.width);val bounds=Rect();assertTrue(badge.getGlobalVisibleRect(bounds));assertEquals("First badge clipped horizontally",badge.width,bounds.width());assertEquals("First badge clipped vertically",badge.height,bounds.height());assertTrue(badge.paint.measureText(badge.text.toString())<badge.width);c.pause().stop().destroy()}

}
